<script setup>
import { ref, onMounted,onUnmounted } from 'vue'
import { X, Plus } from 'lucide-vue-next'
const props=defineProps({columns:Array,existingCategories:Array,initialColumn:{default:'todo'}})
const emit=defineEmits(['submit','close'])
const title=ref(''),description=ref(''),category=ref(''),columnId=ref(props.initialColumn),titleInput=ref(null),dialog=ref(null)
let previous,overflow
onMounted(()=>{previous=document.activeElement;overflow=document.body.style.overflow;document.body.style.overflow='hidden';titleInput.value.focus()})
onUnmounted(()=>{document.body.style.overflow=overflow;previous?.focus?.()})
function submit(){if(!title.value.trim())return;emit('submit',{title:title.value.trim(),description:description.value.trim(),category:category.value.trim(),columnId:columnId.value})}
function trap(e){if(e.key!=='Tab')return;const items=dialog.value.querySelectorAll('button,input,textarea,select');const first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}
</script>
<template><Teleport to="body"><div class="modal-backdrop" @click.self="emit('close')" @keydown.esc="emit('close')"><section ref="dialog" class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title" @keydown="trap"><div class="modal-head"><div><span class="eyebrow">A SMALL STEP FORWARD</span><h2 id="modal-title">记录一件想做的事</h2></div><button class="icon-btn" aria-label="关闭" @click="emit('close')"><X :size="20"/></button></div><form @submit.prevent="submit"><label>任务标题 <span>*</span><input ref="titleInput" v-model="title" maxlength="120" required placeholder="接下来，你想完成什么？"></label><label>补充描述<textarea v-model="description" maxlength="2000" rows="4" placeholder="写下细节，让行动更清晰…"></textarea></label><div class="form-row"><label>分类<input v-model="category" list="categories" maxlength="30" placeholder="例如：工作、生活"><datalist id="categories"><option v-for="c in existingCategories" :key="c" :value="c"/></datalist></label><label>任务状态<select v-model="columnId"><option v-for="col in columns" :key="col.id" :value="col.id">{{col.title}}</option></select></label></div><div class="modal-footer"><span>小步前进，也是一种进步。</span><button type="button" class="secondary-btn" @click="emit('close')">取消</button><button type="submit" class="primary-btn" :disabled="!title.trim()"><Plus :size="16"/>创建任务</button></div></form></section></div></Teleport></template>
<style scoped>.modal-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:25px}h2{font-size:23px;font-weight:600;margin:8px 0}label{display:block;font-size:12px;color:var(--muted);margin-bottom:20px}label span{color:var(--accent)}input,textarea,select{display:block;width:100%;margin-top:9px;background:var(--surface);border:1px solid var(--line);border-radius:10px;padding:12px;color:var(--text);font:inherit;font-size:13px}textarea{resize:vertical}.form-row{display:grid;grid-template-columns:1fr 1fr;gap:16px}.modal-footer{display:flex;align-items:center;gap:10px;margin-top:12px;padding-top:20px;border-top:1px solid var(--line)}.modal-footer>span{font-size:10px;color:var(--muted);margin-right:auto}@media(max-width:500px){.modal-footer>span{display:none}}</style>
